window.ST26_SNAPSHOT={"time": "2026-11-25 10:37", "html": "<!doctype html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<title>SmartTopo 2026<\/title>\n<meta name=\"claude:viewport-fit-sides\" content=\"cover\">\n<meta name=\"description\" content=\"더 빠르고, 더 쉽게, 현장 중심으로. 새 SmartTopo의 신기능을 소개합니다.\">\n<!-- 단독으로 열어볼 때만 쓰는 스타일입니다. 사이트에는 아래 <div id=\"st26\"> 블록만 넣으면 됩니다. -->\n<style>body{margin:0;background:#f1f1f6}<\/style>\n<\/head>\n<body>\n\n<!-- ===== SmartTopo 2026 소개 페이지 시작 (사이트에 넣을 부분) ===== -->\n<div id=\"st26\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Asta+Sans:wght@300..800&display=swap\">\n<style>\n/* SmartTopo 2026 소개 — 이 <div id=\"st26\"> 블록 하나가 페이지 전체입니다(폰트·CSS·마크업·스크립트).\n   CSS는 모두 #st26#st26 안에 중첩되어 있어 사이트 CSS의 영향을 받지 않고, 사이트에도 영향을 주지 않습니다. */\n@keyframes st26-ring{from{width:20%;height:20%;opacity:1}to{width:100%;height:100%;opacity:0}}\n@keyframes st26-float{50%{transform:translateY(-10px)}}\n@keyframes st26-ld{from{opacity:0;transform:translateY(18px)}}\n@keyframes st26-up{from{transform:translateY(105%)}}\n@keyframes st26-rise{from{opacity:0;transform:translateY(60px) rotate(4deg) scale(.94)}}\n@keyframes st26-pop{from{opacity:0;transform:translateY(14px) scale(.9)}}\n@keyframes st26-rv{from{opacity:0;transform:translateY(56px)}}\n@keyframes st26-cut{from{transform:scaleX(0)}}\n@keyframes st26-in{from{opacity:0;transform:translateX(28%) scale(.94);filter:brightness(1.25)}to{opacity:1;transform:none;filter:none}}\n@keyframes st26-out{from{opacity:1;transform:none}to{opacity:0;transform:translateX(-18%) scale(.94)}}\n@keyframes st26-blink{0%{opacity:0}25%{opacity:.55}100%{opacity:0}}\n@keyframes st26-tap{from{transform:scale(.35);opacity:1}to{transform:scale(1.9);opacity:0}}\n@keyframes st26-tapdot{0%{transform:scale(.5);opacity:0}15%{transform:scale(1);opacity:1}65%{transform:scale(.92);opacity:1}100%{transform:scale(.8);opacity:0}}\n/* 사이트(stopo.co.kr 제품소개) 안에 들어갔을 때: 서브 탭 바로 아래에서 히어로가 시작되도록 콘텐츠 영역 상단 여백 제거.\n   이 블록이 있는 페이지에서만 적용됩니다. */\n#contents .subCont:has(#st26){padding-top:0}\n#st26#st26{\n  --navy:#003054;      /* app header */\n  --blue:#019aeb;      /* app primary */\n  --blue-ink:#0063a3;  /* symbol */\n  --amber:#e49325;     /* status pills */\n  --stop:#d23b3b;      /* 측량중지 */\n  --bg:#f1f1f6;        /* app background */\n  --surface:#ffffff;\n  --ink:#16222d;\n  --ink-2:#56636f;\n  --line:#dde1ea;\n  --chip:#e9edf3;\n  --blue-soft:#e2f3fd;\n  --amber-soft:#fcefdc;\n  --f-display:\"Asta Sans\",\"Apple SD Gothic Neo\",\"Malgun Gothic\",system-ui,sans-serif;\n  --f-body:\"Asta Sans\",\"Apple SD Gothic Neo\",\"Malgun Gothic\",system-ui,sans-serif;\n  --f-mono:\"Asta Sans\",\"Apple SD Gothic Neo\",\"Malgun Gothic\",system-ui,sans-serif;\n  --r:18px;\n  --ease:cubic-bezier(.2,.8,.2,1);\n  color-scheme:light;\n  background:var(--bg);color:var(--ink);font-family:var(--f-body);font-size:18px;line-height:1.65;letter-spacing:normal;text-align:left;\n  -webkit-font-smoothing:antialiased;overflow-x:clip;word-break:keep-all;overflow-wrap:break-word;\n\n  /* host-site reset: the site sets font, line-height and letter-spacing on every element (*{}) */\n  & *,& *::before,& *::after{box-sizing:border-box;font-family:inherit;line-height:inherit;letter-spacing:inherit}\n  & h1,& h2,& h3{color:inherit;padding:0}\n  & h1::after,& h2::after,& h3::after{content:none}\n  & ul{margin:0}\n\n  /* Layout: navy field-survey hero with live RTK readout → scroll-synced phone stage for 6 features → update rail (Stakeout nav card first) → controller specs → key points → GS certification → closing band (앱 다운로드 · 동영상 매뉴얼) */\n  & a{color:inherit}\n  & img,& video{display:block;max-width:100%}\n  & h1,& h2,& h3{text-wrap:balance;margin:0;line-height:1.25;letter-spacing:-.02em}\n  & p{margin:0; font-weight: 500; font-size:16px}\n  .wrap{max-width:1200px;margin-inline:auto;padding-left:max(20px,env(safe-area-inset-left,0px));padding-right:max(20px,env(safe-area-inset-right,0px))}\n  .mono{font-family:var(--f-mono);font-variant-numeric:tabular-nums}\n  .eyebrow{font-family:var(--f-mono);font-size:24px;color:var(--blue); margin-left:5px;font-weight:700}\n  :focus-visible{outline:2px solid var(--blue);outline-offset:3px;border-radius:6px}\n  .btn{display:inline-flex;align-items:center;gap:8px;border:0;cursor:pointer;font:600 18px/1 var(--f-body);padding:13px 22px;border-radius:999px;text-decoration:none;transition:transform .35s var(--ease),background .2s,box-shadow .3s}\n  .btn-blue{background:var(--blue);color:#fff;box-shadow:0 8px 20px -10px rgba(1,154,235,.6)}\n  .btn-blue:hover{background:#0b8fd6}\n  .btn-ghost{background:var(--surface);color:var(--navy);}\n  .btn svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}   /* 앱 다운로드 아이콘 (메인 section01과 같은 모양) */\n  .btn-ghost:hover{background:var(--blue-soft);border-color:var(--blue)}\n  @media (max-width:820px){.nav ul{display:none}.nav .btn{margin-left:auto}}\n  /* ---------- hero ---------- */\n  .hero{position:relative;background:var(--bg);color:var(--ink);overflow:hidden;isolation:isolate}\n  .hero canvas{position:absolute;inset:0;width:100%;height:100%;z-index:-1;opacity:.9}\n  .hero .wrap{display:grid;grid-template-columns:1.1fr .9fr;gap:40px;align-items:center;padding-block:88px 96px}\n  .hero h1{font-size:clamp(36px,4vw,64px);font-weight:800;letter-spacing:-.035em;line-height:1.08;color:var(--navy)}\n  .hero h1 .k{display:block;overflow:hidden}\n  .hero h1 .k>span{display:inline-block}\n  .hero h1 em{font-style:normal;color:var(--amber)}\n  .hero .eyebrow{color:var(--blue)}\n  .hero .hero-logo{display:block;height:clamp(26px,2.6vw,40px);width:auto; margin-left:6px;}\n  .hero .lead{margin-top:26px;max-width:34em;color:var(--ink-2);font-size:18px}\n  .hero .ctas{display:flex;gap:12px;flex-wrap:wrap;margin-top:34px}\n  .hero-stage{position:relative;justify-self:center;width:min(330px,80vw)}\n  .readout{position:absolute;z-index:3;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:12px 14px;font-family:var(--f-mono);font-size:12.5px;color:var(--navy);font-weight:500;box-shadow:0 18px 36px -20px rgba(0,48,84,.45);white-space:nowrap;transition:transform .6s var(--ease)}\n  .readout .lbl{color:var(--ink-2);font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;display:block;margin-bottom:6px}\n  .readout.r1{left:-216px;top:60px}\n  .readout.r2{right:-118px;top:300px}\n  .readout.r3{left:-164px;bottom:60px}\n  .readout .row{display:flex;justify-content:space-between;gap:16px}\n  .readout .ok{color:var(--blue)}\n  /* r2 상태 칩: Figma 69:116319 (모양만 참고 · 값은 목업 영상과 같게 — 남색 블록 안에 칩 4개, 칩 42px·모서리 16px, 라벨 10px 흰색 70% + 값 14px) */\n  .pill{display:inline-flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;width:42px;padding:8px 6px;border-radius:16px;font:700 10px/1 var(--f-body);color:rgba(241,241,246,.7);white-space:nowrap;text-align:center}\n  .pill b{font-size:14px;line-height:1;color:#fff;font-weight:700}\n  .pill.a{background:var(--amber)}\n  .pill.b{background:var(--blue)}\n  .readout.r2{display:flex;gap:6px;padding:8px;background:var(--navy);border:0;border-radius:22px;box-shadow:0 18px 36px -18px rgba(0,48,84,.6)}   /* 칩 뒤 남색 블록 (r1과 같은 톤) */\n  /* r3 정밀도 카드: Figma 69:116344 체크박스 행을 세로로 — 남색 블록, 체크 18px + 라벨(흰색 70%) + 값(흰색) 16px */\n  .readout.r3{background:var(--navy);border:0;border-radius:16px;padding:16px 18px;display:grid;gap:9px;font:600 16px/1 var(--f-body);color:rgba(241,241,246,.7);font-variant-numeric:tabular-nums;box-shadow:0 18px 36px -18px rgba(0,48,84,.6)}\n  .readout.r3 .row{justify-content:flex-start;align-items:center;gap:6px;font-size:inherit;line-height:1}\n  .readout.r3 .ck{display:block;width:18px;height:18px;flex:none}\n  .readout.r3 .ok{color:#f1f1f6;margin-left:-2px}\n  /* r1 좌표 카드: Figma 82:125104 기반 — 남색 불투명, 흰색 굵은 17px, 휴대폰 목업과 간격 둠 */\n  .readout.r1{background:var(--navy);border:0;border-radius:16px;padding:16px 18px;display:grid;gap:7px;font:700 17px/1 var(--f-body);color:#f1f1f6;font-variant-numeric:tabular-nums;box-shadow:0 18px 36px -18px rgba(0,48,84,.6)}\n  .readout.r1 .row{justify-content:flex-start;gap:8px;font-size:inherit;line-height:1}   /* 사이트 CSS가 div를 13px로 고정해서 상속으로 되돌림 */\n  .readout.r1 .row>span:first-child{width:40px;flex:none}\n  @media (max-width:960px){\n    .hero .wrap{grid-template-columns:1fr;padding-block:64px 72px}\n    .readout.r1{left:-14px;top:40px}.readout.r2{right:-14px;top:auto;bottom:150px}.readout.r3{left:-14px;bottom:24px}\n  }\n  @media (max-width:420px){.readout{font-size:11px}.readout.r1{left:-8px;font-size:13px;padding:12px 14px;border-radius:12px;gap:5px}.readout.r1 .row>span:first-child{width:32px}.readout.r3{left:-8px;font-size:13px;padding:12px 14px;gap:7px}.readout.r3 .ck{width:15px;height:15px}.readout.r2{right:-8px}}\n  /* reticle */\n  .reticle{position:absolute;pointer-events:none;z-index:1;inset:0;opacity:0;transition:opacity .3s}\n  .hero:hover .reticle{opacity:1}\n  .reticle i{position:absolute;background:rgba(0,99,163,.22)}\n  .reticle .h{left:0;right:0;height:1px}\n  .reticle .v{top:0;bottom:0;width:1px}\n  .reticle .tag{position:absolute;font-family:var(--f-mono);font-size:11px;color:var(--blue-ink);padding:4px 8px;background:var(--surface);border:1px solid var(--line);border-radius:6px;transform:translate(12px,12px);white-space:nowrap}\n  @media (hover:none){.reticle{display:none}}\n  /* ---------- phone ---------- */\n  /* Android-style device. Every part of the chrome (bezel, metal band, buttons, status bar) is sized in --k,\n     one \"hero pixel\": the hero phone is 330px wide, so a phone drawn at any width keeps the hero's proportions. */\n  .phone{position:relative;width:100%;container-type:inline-size}\n  .phone .shell{--k:calc(100cqw / 330);position:relative;padding:calc(10 * var(--k));border-radius:calc(30 * var(--k));background:#08090b;\n    box-shadow:inset 0 0 0 calc(1 * var(--k)) #24272b,0 0 0 calc(1.5 * var(--k)) #a9aeb5,0 0 0 calc(4.5 * var(--k)) #5d6168,0 0 0 calc(6 * var(--k)) #33363b,0 0 0 calc(7 * var(--k)) #9ba0a7,\n    0 calc(46 * var(--k)) calc(70 * var(--k)) calc(-34 * var(--k)) rgba(0,48,84,.6),0 calc(18 * var(--k)) calc(30 * var(--k)) calc(-22 * var(--k)) rgba(0,0,0,.45)}\n  .phone .shell::before,.phone .shell::after{content:\"\";position:absolute;width:calc(4 * var(--k));background:#6b7077;border:calc(1 * var(--k)) solid #4a4e54}\n  .phone .shell::before{left:calc(-11 * var(--k));top:17%;height:calc(46 * var(--k));border-radius:calc(3 * var(--k)) 0 0 calc(3 * var(--k));box-shadow:0 calc(64 * var(--k)) 0 calc(-1 * var(--k)) #6b7077,0 calc(-54 * var(--k)) 0 calc(-9 * var(--k)) #6b7077}\n  .phone .shell::after{right:calc(-11 * var(--k));top:24%;height:calc(78 * var(--k));border-radius:0 calc(3 * var(--k)) calc(3 * var(--k)) 0}\n  .phone .screen{position:relative;width:100%;border-radius:calc(20 * var(--k));overflow:hidden;background:var(--navy);display:flex;flex-direction:column;isolation:isolate}\n  .phone .sbar{flex:none;height:calc(38 * var(--k));display:flex;align-items:flex-end;justify-content:space-between;padding:0 calc(18 * var(--k)) calc(7 * var(--k));background:var(--navy);color:#fff;font:600 calc(13 * var(--k))/1 var(--f-body);letter-spacing:.01em;font-variant-numeric:tabular-nums}\n  .phone .sbar .ic{display:flex;align-items:center;gap:calc(5 * var(--k))}\n  .phone .sbar svg{display:block;height:calc(13 * var(--k));width:auto;fill:#fff}\n  .phone .foot{flex:none;height:calc(26 * var(--k));background:var(--foot,#f0f1f4)}   /* 하단 띠 색은 화면(영상)마다 다름: 기능 데이터의 fc 값을 --foot 으로 넣음 */\n  /* white strip under the app's bottom menu (no home indicator) */\n  .phone .sbar .bt{font-size:calc(11.5 * var(--k));margin-left:calc(1 * var(--k))}\n  .phone .media{position:relative;flex:none;width:100%;aspect-ratio:400/766;overflow:hidden;background:var(--bg)}\n  .phone .media>*{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:top}\n  /* ---------- sections ---------- */\n  & section{position:relative}\n  .sec{padding-block:120px}\n  .sec-head{display:grid;gap:8px;max-width:720px;margin-bottom:56px}\n  .sec-head h2{font-size:clamp(36px,4vw,64px);font-weight:800;margin-bottom:0}\n  .sec-head p{color:var(--amber);}\n  .features{background:var(--surface);padding-bottom:0}\n  .fgrid{display:grid;grid-template-columns:minmax(0,1fr) 380px;gap:80px;position:relative;z-index:0}\n  /* 기능 6개를 각각 화면 가로 전체 띠로: 섹션 제목+1·3·5 흰색(제목과 1번은 한 덩어리), 2·4·6 그레이 */\n  .fitem{position:relative}\n  .fitem::before{content:\"\";position:absolute;inset:0;background:#fbfbfd;box-shadow:0 0 0 100vmax #fbfbfd;clip-path:inset(0 -100vmax);z-index:-1}   /* 가로 전체 띠: 넓은 박스 대신 그림자로 늘려서 가로 스크롤·잘라내기(overflow clip) 없이 그림 → 사파리 고정 목업 흔들림 방지 */   /* 2·4·6: 기본 그레이(#f1f1f6)보다 훨씬 연하게 */\n  .fitem:nth-child(odd)::before{background:var(--surface);box-shadow:0 0 0 100vmax var(--surface)}\n  .fgrid>.flist{padding-right:16px}\n  .stage{position:sticky;top:70px;height:calc(100vh - 140px);max-height:820px;display:flex;align-items:center;justify-content:center;gap:24px}\n  .stage .phone{width:min(310px,calc((100vh - 230px) * .47));flex:none}\n  /* 목업 화면 전환: 비슷한 화면끼리도 바뀐 게 보이도록 새 화면은 오른쪽에서 밀려 들어오고, 이전 화면은 왼쪽으로 빠지며 흐려짐 + 화면 위 살짝 번쩍임 */\n  .stage .media>video,.stage .media>img{opacity:0}\n  /* 하단 흰 띠(.foot)도 화면과 한 장처럼 같이 전환: 목업(스테이지)에서는 .foot 대신 각 영상·사진 아래에 같은 띠를 붙임 */\n  .stage .phone .foot{display:none}\n  .stage .phone .media{aspect-ratio:330/657.95}\n  .stage .media>video,.stage .media>img{box-sizing:content-box;bottom:auto;height:auto;aspect-ratio:400/766;border-bottom:calc(26 * var(--k)) solid var(--foot,#f0f1f4)}\n  .stage .media>.on{opacity:1;z-index:2;animation:st26-in .7s var(--ease) both}\n  .stage .media>.was{z-index:1;animation:st26-out .7s var(--ease) both}\n  .stage .media::after{content:\"\";position:absolute;inset:0;z-index:3;background:#fff;opacity:0;pointer-events:none}\n  .stage .media.swap::after{animation:st26-blink .5s ease-out}\n  /* 영상 속 하단 메뉴 터치를 또렷하게: 녹화된 터치 시점에 맞춰 영상 위에 터치 효과(퍼지는 링 + 눌리는 점) */\n  .phone>.tapfx{position:absolute;z-index:6;width:80px;height:80px;border-radius:50%;transform:translate(-50%,-50%);pointer-events:none}   /* 휴대폰 틀 위에 띄움: 영상 영역·하단(.foot)에 잘리지 않고 목업 밖으로 나가도 됨 */\n  .tapfx::before{content:\"\";position:absolute;inset:0;border-radius:50%;background:rgba(1,154,235,.28);border:3px solid rgba(1,154,235,.9);animation:st26-tap .75s ease-out forwards}\n  .tapfx::after{content:\"\";position:absolute;inset:36%;border-radius:50%;background:rgba(255,255,255,.95);box-shadow:0 0 0 4px rgba(1,154,235,.9),0 4px 10px rgba(0,48,84,.35);animation:st26-tapdot .75s ease-out forwards}\n  .rail{display:flex;flex-direction:column;align-items:center;gap:14px;font-family:var(--f-mono);font-size:18px;color:var(--ink-2)}\n  .rail i{position:relative;display:block;width:8px;height:8px;border-radius:50%;background:var(--line);transition:background .3s,transform .4s var(--ease)}\n  .rail i.on{background:var(--blue);transform:scale(1)}\n  .rail i span{position:absolute;right:calc(100% + 12px);top:50%;transform:translate(6px,-50%);white-space:nowrap;font:600 18px/1 var(--f-body);font-style:normal;color:var(--blue);opacity:0;pointer-events:none;transition:opacity .3s,transform .4s var(--ease)}\n  .rail i.on span{opacity:1;transform:translate(0,-50%)}\n  .fitem{min-height:68vh;display:flex;flex-direction:column;justify-content:center;gap:20px;padding-block:100px}\n  .fitem .no{font-family:var(--f-display);font-size:24px;font-weight:800;color:var(--blue);display:flex;align-items:center;gap:12px}\n  .fitem .no::after{content:\"\";height:2px;width:80px;background:currentColor;}\n  .fitem h3{font-size:clamp(28px,3.4vw,42px);font-weight:800}\n  .fitem .sum{font-size:24px;font-weight:700;color:var(--ink)}\n  .fitem p.desc{color:var(--ink-2);font-size:18px;max-width:30em; line-height:1.6;}\n  .thumbs{display:flex;gap:12px;flex-wrap:wrap;margin-top:8px}\n  .thumb{width:96px;aspect-ratio:540/1033;border-radius:14px;overflow:hidden;border:2px solid var(--line);padding:0;cursor:pointer;background:var(--bg);transition:transform .35s var(--ease),border-color .2s,opacity .3s}\n  .thumb img{width:100%;height:100%;object-fit:cover;object-position:top}\n  .thumb:hover{transform:translateY(-4px);opacity:.8}\n  .thumb[aria-pressed=\"false\"]{opacity:.4}   /* 선택 안 된 섬네일은 반투명 */\n  .thumb[aria-pressed=\"false\"]:hover{opacity:1}   /* 마우스를 올리면 다시 선명하게 */\n  .thumb[aria-pressed=\"true\"]{border-color:var(--blue);opacity:1;box-shadow:0 8px 18px -10px rgba(1,154,235,.7)}\n  .thumb.vid{display:flex;align-items:center;justify-content:center;flex-direction:column;gap:6px;font:500 18px var(--f-body);color:var(--ink-2)}\n  .thumb.vid svg{width:26px;height:26px;fill:var(--blue)}\n  .report{margin-top:10px;background:var(--bg);border:1px solid var(--line);border-radius:14px;padding:14px;overflow:hidden}\n  .report figcaption{font-family:var(--f-mono);font-size:18px;color:var(--ink-2);margin-bottom:10px}\n  .report img{border-radius:8px;width:100%;transition:transform .8s var(--ease)}\n  .report:hover img{transform:scale(1.04)}\n  .m-phone{display:none}\n  @media (max-width:960px){\n    .fgrid{grid-template-columns:1fr;gap:0}\n    .stage{display:none}\n    .fitem{min-height:0;padding-block:42px;border-bottom:1px solid var(--line)}\n    .fitem:last-child{border-bottom:0}\n    .m-phone{display:block;width:min(280px,72vw);margin:8px auto 0}\n    .thumbs{display:none}\n  }\n  /* updates: Apple-style carousel — light tiles, phone zoomed onto the feature, caption below */\n  .ucar-wrap{position:relative}\n  .ucar{display:flex;gap:22px;overflow-x:auto;scroll-snap-type:x mandatory;scrollbar-width:none;overscroll-behavior-x:contain;\n    --edge:max(20px,calc((100% - 1200px) / 2 + 20px));padding-inline:var(--edge);scroll-padding-inline:var(--edge);padding-bottom:6px}\n  .ucar::-webkit-scrollbar{display:none}\n  .uitem{flex:0 0 clamp(270px,28vw,372px);scroll-snap-align:start;display:grid;gap:22px;align-content:start;margin:0}\n  .utile{position:relative;aspect-ratio:4/5;border-radius:28px;overflow:hidden;background:#ffffff;isolation:isolate}\n  .utile .phone{position:absolute;transition:transform .9s var(--ease)}\n  .utile .phone{transform-origin:50% 50%}\n  .utile .phone.nofoot .foot{display:none}   /* 화면 이미지 아래 하단 띠 없이, 목업 아래 끝을 이미지 끝에 맞춤 */\n  .uitem:hover .utile .phone{transform:scale(1.03)}\n  .uitem figcaption{font-size:18px;line-height:1.55;color:var(--ink-2);padding-inline:6px;max-width:30em; font-weight:500}\n  .uitem figcaption b{color:var(--ink);font-weight:800}\n  .ucar-ctl{display:flex;justify-content:flex-end;gap:12px;margin-top:28px}\n  .ucar-ctl button{width:44px;height:44px;border-radius:50%;border:0;cursor:pointer;background:var(--chip);color:var(--ink);display:grid;place-items:center;transition:background .2s,opacity .2s,transform .3s var(--ease)}\n  .ucar-ctl button:hover:not(:disabled){background:#dde3eb;transform:scale(1.06)}\n  .ucar-ctl button:disabled{opacity:.35;cursor:default}\n  .ucar-ctl svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2.4;stroke-linecap:round;stroke-linejoin:round}\n  @media (max-width:620px){.uitem{flex-basis:80%}.utile{border-radius:22px}}\n  .utile .media>img{transition:opacity .6s}\n  .utile .media>img.off{opacity:0}\n  .utile .tag{position:absolute;left:20px;top:20px;z-index:2;font:700 18px/1 var(--f-body);color:#fff;background:var(--blue);padding:9px 14px;border-radius:999px;font-variant-numeric:tabular-nums}\n  /* controller specs */\n  .specs{background:var(--surface)}\n  .spec-grid{display:grid;grid-template-columns:1fr 1fr;gap:24px}\n  .spec{border:1px solid var(--line);border-radius:28px;padding:40px 44px 28px}\n  .spec.rec{background:var(--bg);border-color:var(--bg)}\n  .spec h3{font-size:30px;font-weight:800;display:flex;align-items:center;gap:12px;margin-bottom:26px}\n  .spec h3 .badge{font-size:18px;font-weight:700;line-height:1;color:#fff;background:var(--blue);padding:8px 13px;border-radius:999px;letter-spacing:0}\n  .spec dl{margin:0;display:grid;grid-template-columns:112px 1fr}\n  .spec dt,.spec dd{margin:0;padding:18px 0;border-top:1px solid var(--line);font-size:18px;line-height:1.5}\n  .spec dt{color:var(--ink-2);font-weight:600}\n  .spec dd{color:var(--ink);font-weight:700}\n  .spec dd small{display:block;margin-top:4px;font-size:18px;font-weight:500;color:var(--ink-2)}\n  .spec-notes{margin-top:36px;display:grid;gap:10px;max-width:60em}\n  .spec-notes p{color:var(--ink-2);padding-left:1.2em;text-indent:-1.2em;line-height:1.6}\n  .spec-notes a{color:var(--blue-ink);text-underline-offset:3px;word-break:break-all}\n  @media (max-width:820px){.spec-grid{grid-template-columns:1fr}.spec{padding:30px 24px 18px}}\n  /* key points */\n  .keypoint{background:var(--navy);color:#fff;overflow:hidden}\n  .keypoint .eyebrow{color:var(--amber)}\n  .keypoint .sec-head h2{color:#fff}\n  .kp{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:16px;list-style:none;padding:0}\n  .kp li{position:relative;display:grid;align-content:start;gap:14px;padding:40px 18px 40px 18px ;border-radius:24px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);transition:background .3s,transform .5s var(--ease)}\n  .kp li:hover{background:rgba(255,255,255,.1);transform:translateY(-4px)}\n  .kp .n{font-size:18px;font-weight:700;color:#6f8aa3;font-variant-numeric:tabular-nums}\n  .kp svg{width:46px;height:46px;fill:none;stroke:var(--amber);stroke-width:1.2;stroke-linecap:round;stroke-linejoin:round;margin-bottom:8px}\n  .kp h3{font-size:20px;font-weight:600;line-height:1.4;color:#fff}\n  .kp p{color:#b9cbdb;line-height:1.5}\n  @media (max-width:1100px){.kp{grid-template-columns:repeat(3,minmax(0,1fr))}}\n  @media (max-width:720px){.kp{grid-template-columns:repeat(2,minmax(0,1fr))}}\n  @media (max-width:460px){.kp{grid-template-columns:1fr}}\n  /* GS certification */\n  .gs{background:var(--bg)}\n  .gs .wrap{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,.8fr);gap:64px;align-items:center}\n  .gs .sec-head{margin-bottom:0}\n  .gs .sec-head h2{margin-bottom:24px;font-size:clamp(32px,3.6vw,52px)}\n  .gs .sec-head p.gs-q{font-weight:800;color:var(--ink);margin-bottom:6px}\n  .gs .sec-head p.gs-txt{color:var(--ink-2);max-width:32em}\n  .marks{display:grid;grid-template-columns:1fr 1fr;gap:20px}\n  .mark{margin:0;background:var(--surface);border-radius:28px;padding:40px 24px 30px;display:grid;justify-items:center;gap:18px;text-align:center}\n  .mark img{width:min(185px,100%);height:auto}\n  .mark figcaption{font-size:18px;font-weight:700;color:var(--ink);line-height:1.45}\n  .mark figcaption span{display:block;font-weight:500;color:var(--ink-2)}\n  .crit{grid-column:1/-1;background:var(--surface);border-radius:28px;padding:28px 32px 30px}\n  .crit p{font-weight:700;color:var(--ink);margin-bottom:14px}\n  .crit ul{display:flex;flex-wrap:wrap;gap:10px;list-style:none;padding:0}\n  .crit li{font-size:18px;font-weight:600;line-height:1;color:var(--blue-ink);background:var(--blue-soft);padding:11px 16px;border-radius:999px}\n  @media (max-width:960px){.gs .wrap{grid-template-columns:1fr;gap:48px}}\n  @media (max-width:460px){.marks{grid-template-columns:1fr}}\n  /* closing */\n  .closing{background:var(--blue);color:#fff;text-align:center;overflow:hidden}\n  .closing .btn-blue{background:var(--navy);box-shadow:none}\n  .closing .btn-blue:hover{background:#00243f}\n  .closing .btn-ghost{border-color:var(--surface);color:var(--blue)}\n  .closing .btn-ghost:hover{background:var(--amber-soft);color:var(--navy)}\n  .closing .wrap{padding-block:160px;display:grid;justify-items:center;gap:22px}\n  .closing img.sym{width:clamp(180px,18vw,240px);height:auto;animation:st26-float 6s ease-in-out infinite}\n  .closing h2{font-size:clamp(32px,4.6vw,56px);color:#fff;font-weight:700}\n  .closing p{color:rgba(255,255,255,.88);max-width:34em; font-size:22px; line-height:1.5}\n\n\n  /* ---------- motion ---------- */\n  /* 모바일 글자 크기: h1 46 · h2 40 · h3 40 · 키포인트 h3 28 */\n  @media (max-width:768px){\n    .hero h1{font-size:46px}\n    .sec-head h2,.gs .sec-head h2,.closing h2{font-size:40px}\n    .fitem h3,.spec h3{font-size:40px}\n    .kp h3{font-size:28px}\n  }\n  /* 6가지 기능: 한 줄로 쌓이는 화면(태블릿·모바일)에서는 가운데 정렬 */\n  @media (max-width:960px){\n    .hero .wrap>div:first-child{text-align:center}   /* 히어로: 한 줄로 쌓이는 화면에서는 글·버튼 가운데 정렬 */\n    .hero .hero-logo{margin-inline:auto}\n    .hero .lead{margin-inline:auto}\n    .hero .ctas{justify-content:center}\n    .fitem{align-items:center;text-align:center}\n    .fitem .no{justify-content:center}\n    .fitem p.desc{margin-inline:auto}\n  }\n  @media (prefers-reduced-motion:no-preference){\n    .ld{animation:st26-ld 1s var(--ease) both;animation-delay:calc(var(--d,0) * 90ms + 150ms)}\n    .hero h1 .k>span{animation:st26-up 1s var(--ease) both;animation-delay:calc(var(--d,0) * 110ms + 100ms)}\n    .hero-stage .phone{animation:st26-rise 1.3s var(--ease) both .35s}\n    .readout{animation:st26-pop .9s var(--ease) both;animation-delay:calc(var(--d,0) * 160ms + 900ms)}    \n    @supports (animation-timeline: view()){\n      .rv{animation:st26-rv linear both;animation-timeline:view();animation-range:entry 0% entry 70%}  \n    }\n  }\n  @media (prefers-reduced-motion:reduce){\n    .closing img.sym{animation:none}\n    .stage .media>*,.utile .media>img{transition:none}\n    .stage .media>*,.stage .media.swap::after{animation:none}\n    .tapfx{display:none}\n  }\n}\n<\/style>\n<div class=\"st-main\">\n<section class=\"hero\" aria-labelledby=\"hero-title\">\n  <canvas id=\"topo\" aria-hidden=\"true\"><\/canvas>\n  <div class=\"reticle\" aria-hidden=\"true\"><i class=\"h\"><\/i><i class=\"v\"><\/i><span class=\"tag\"><\/span><\/div>\n  <div class=\"wrap\">\n    <div>\n      <img class=\"hero-logo ld\" style=\"--d:0\" src=\"assets/smarttopo_logo.svg\" alt=\"SmartTopo\" width=\"191\" height=\"34\">\n      <h1 id=\"hero-title\" style=\"margin-top:18px\">\n        <span class=\"k\"><span style=\"--d:1\">더 빠르고, 더 쉽게<\/span><\/span>\n        <span class=\"k\"><span style=\"--d:3\"><em>현장 중심으로<\/em><\/span><\/span>\n      <\/h1>\n      <p class=\"lead ld\" style=\"--d:5\">새로운 SmartTopo는 측량 현장의 작업 단계를 줄이는 데 집중했습니다. <br>지도에서 바로 측량·측설을 시작할 수 있으며, 사진 좌표 획득과 공공측량용 기준점측량 기능 탑재로 한층 폭넓은 측량 업무를 완성합니다.<\/p>\n      <div class=\"ctas ld\" style=\"--d:6\">\n        <a class=\"btn btn-blue mag\" href=\"#features\">새로운 기능 살펴보기 <span aria-hidden=\"true\">↓<\/span><\/a>\n        <a class=\"btn btn-ghost mag\" href=\"https://play.google.com/store/apps/details?id=kr.co.geosys.SmartTopo207\" target=\"_blank\" rel=\"noopener\">앱 다운로드 <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 4v11M7 10.5l5 5 5-5M5 19.5h14\"/><\/svg><\/a>\n      <\/div>\n    <\/div>\n    <div class=\"hero-stage\" id=\"heroStage\">\n      <div class=\"phone\" style=\"--foot:#fbfefb\"><div class=\"screen\">\n        <video src=\"assets/hero.mp4\" poster=\"assets/s2a.webp\" autoplay muted loop playsinline aria-label=\"빠른 측설, 사진 측량, 측량 단계 간소화 화면 녹화\"><\/video>\n      <\/div><\/div>\n      <div class=\"readout r1\" style=\"--d:0\" data-depth=\"18\">\n        <div class=\"row\"><span>X(N)<\/span><span id=\"cx\">549278.428<\/span><\/div>\n        <div class=\"row\"><span>Y(E)<\/span><span id=\"cy\">194656.079<\/span><\/div>\n        <div class=\"row\"><span>Z(H)<\/span><span id=\"cz\">27.063<\/span><\/div>\n      <\/div>\n      <div class=\"readout r2\" style=\"--d:1\" data-depth=\"-14\" aria-label=\"수신 상태\">\n        <span class=\"pill a\">IMU<b>OFF<\/b><\/span><span class=\"pill b\">GNSS<b id=\"gn\">16<\/b><\/span><span class=\"pill b\">보정<b>양호<\/b><\/span><span class=\"pill b\">상태<b>고정<\/b><\/span>\n      <\/div>\n      <div class=\"readout r3\" style=\"--d:2\" data-depth=\"10\">\n        <div class=\"row\"><img class=\"ck\" src=\"assets/check_on.svg\" alt=\"\" width=\"18\" height=\"18\"><span>PDOP<\/span><span class=\"ok\" id=\"pd\">1.7<\/span><\/div>\n        <div class=\"row\"><img class=\"ck\" src=\"assets/check_on.svg\" alt=\"\" width=\"18\" height=\"18\"><span>H<\/span><span class=\"ok\" id=\"ph\">0.017<\/span><\/div>\n        <div class=\"row\"><img class=\"ck\" src=\"assets/check_on.svg\" alt=\"\" width=\"18\" height=\"18\"><span>V<\/span><span class=\"ok\" id=\"pv\">0.030<\/span><\/div>\n      <\/div>\n    <\/div>\n  <\/div>\n<\/section>\n\n<section class=\"sec features\" id=\"features\" aria-labelledby=\"feat-title\">\n  <div class=\"wrap\">\n    <div class=\"sec-head rv\">\n      <p class=\"eyebrow\">6 new features<\/p>\n      <h2 id=\"feat-title\">새로운 SmartTopo의 새로운 기능<\/h2>\n    <\/div>\n    <div class=\"fgrid\">\n      <div class=\"flist\" id=\"flist\"><\/div>\n      <aside class=\"stage\" aria-label=\"기능 화면 미리보기\">\n        <div class=\"rail\" id=\"rail\" aria-hidden=\"true\"><\/div>\n        <div class=\"phone\"><div class=\"screen\" id=\"stageScreen\"><\/div><\/div>\n      <\/aside>\n    <\/div>\n  <\/div>\n<\/section>\n\n<section class=\"sec\" id=\"updates\" aria-labelledby=\"up-title\">\n  <div class=\"wrap\">\n    <div class=\"sec-head rv\">\n      <p class=\"eyebrow\">More updates<\/p>\n      <h2 id=\"up-title\">그 밖의 업데이트<\/h2>\n    <\/div>\n  <\/div>\n  <div class=\"ucar-wrap\">\n    <div class=\"ucar\" id=\"ucar\" role=\"region\" aria-label=\"그 밖의 업데이트 목록\" tabindex=\"0\"><\/div>\n    <div class=\"wrap\"><div class=\"ucar-ctl\">\n      <button type=\"button\" id=\"ucPrev\" aria-label=\"이전 업데이트\"><svg viewBox=\"0 0 24 24\"><path d=\"M15 5l-7 7 7 7\"/><\/svg><\/button>\n      <button type=\"button\" id=\"ucNext\" aria-label=\"다음 업데이트\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 5l7 7-7 7\"/><\/svg><\/button>\n    <\/div><\/div>\n  <\/div>\n<\/section>\n\n<section class=\"sec specs\" id=\"specs\" aria-labelledby=\"sp-title\">\n  <div class=\"wrap\">\n    <div class=\"sec-head rv\">\n      <p class=\"eyebrow\">Controller specs<\/p>\n      <h2 id=\"sp-title\">스마트토포 컨트롤러 사양<\/h2>\n    <\/div>\n    <div class=\"spec-grid rv\">\n      <div class=\"spec\">\n        <h3>최소사양<\/h3>\n        <dl>\n          <dt>태블릿<\/dt><dd>Galaxy Tab Active3<\/dd>\n          <dt>스마트폰<\/dt><dd>Galaxy S10<\/dd>\n          <dt>RAM<\/dt><dd>4GB 이상<\/dd>\n          <dt>AR<\/dt><dd>ARCore 지원<\/dd>\n          <dt>운영체제<\/dt><dd>Android 7 이상<\/dd>\n        <\/dl>\n      <\/div>\n      <div class=\"spec rec\">\n        <h3>권장사양 <span class=\"badge\">추천<\/span><\/h3>\n        <dl>\n          <dt>태블릿<\/dt><dd>Galaxy Tab Active5<\/dd>\n          <dt>스마트폰<\/dt><dd>Galaxy S21 시리즈 이상<\/dd>\n          <dt>RAM<\/dt><dd>6GB 이상<\/dd>\n          <dt>AR<\/dt><dd>ARCore 지원<\/dd>\n          <dt>운영체제<\/dt><dd>Android 14 이상<\/dd>\n        <\/dl>\n      <\/div>\n    <\/div>\n    <div class=\"spec-notes rv\">\n      <p>※ AR 기능은 ARCore를 지원하는 기기에서 사용할 수 있습니다. <br>지원 기기 확인: <a href=\"https://developers.google.com/ar/devices\" target=\"_blank\" rel=\"noopener\">developers.google.com/ar/devices<\/a><\/p>\n      <p>※ 스마트토포는 위성측량장비를 제어하는 고정밀측량 앱입니다. 로그인 방식으로 사용권한이 부여되며,<br> ‘내업’을 통하여 GNSS 연결 이외의 기능을 사용하고 확인할 수 있습니다.<\/p>\n    <\/div>\n  <\/div>\n<\/section>\n\n<section class=\"sec keypoint\" id=\"keypoint\" aria-labelledby=\"kp-title\">\n  <div class=\"wrap\">\n    <div class=\"sec-head rv\">\n      <p class=\"eyebrow\">Key point<\/p>\n      <h2 id=\"kp-title\">스마트토포 Key Point<\/h2>\n    <\/div>\n    <ul class=\"kp rv\">\n      <li><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"12\" cy=\"9\" r=\"6\"/><path d=\"M8.6 13.9 7 22l5-3 5 3-1.6-8.1\"/><path d=\"m9.8 9 1.5 1.5L14.4 7.6\"/><\/svg><h3>한국정보통신기술협회 우수 소프트웨어 인증<\/h3><p>GS (Good Software) 1등급<\/p><\/li>\n      <li><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M8 7l-5 5 5 5M16 7l5 5-5 5M13.8 4.5l-3.6 15\"/><\/svg><h3>개발전담부서를 통한 지속적인 유지관리<\/h3><p>업계 유일 R&amp;D팀 자체 개발 및 운영<\/p><\/li>\n      <li><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 13.5V21M8 21h8\"/><circle cx=\"12\" cy=\"10.5\" r=\"3\"/><path d=\"M6.6 5.1a7.6 7.6 0 0 0 0 10.8M17.4 5.1a7.6 7.6 0 0 1 0 10.8\"/><\/svg><h3>최고 사양 Trimble 수신기와의 유일한 호환<\/h3><p>Trimble, Spectra 제품 적용 가능<\/p><\/li>\n      <li><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3v12M7 10.5l5 5 5-5M4 17v3.5h16V17\"/><\/svg><h3>누적 다운로드 3만회 돌파<\/h3><p>업계 최다 사용자 수<\/p><\/li>\n      <li><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3 2.5 8 12 13l9.5-5L12 3z\"/><path d=\"m2.5 12.5 9.5 5 9.5-5\"/><path d=\"m2.5 17 9.5 5 9.5-5\"/><\/svg><h3>다양한 업무 환경지원<\/h3><p>GNSS / TotalStation / 드론 등<\/p><\/li>\n    <\/ul>\n  <\/div>\n<\/section>\n\n<section class=\"sec gs\" id=\"gs\" aria-labelledby=\"gs-title\">\n  <div class=\"wrap\">\n    <div class=\"sec-head rv\">\n      <p class=\"eyebrow\">GS certified<\/p>\n      <h2 id=\"gs-title\">국내 유일 GS 인증<br>측량 안드로이드 솔루션<\/h2>\n      <p class=\"gs-q\">GS인증이란?<\/p>\n      <p class=\"gs-txt\">한국정보통신기술협회 TTA(소프트웨어시험인증연구소)에서 ISO/IEC 25023, 25041, 25051 국제표준을 기반으로 기능적합성, 성능효율성, 사용성, 신뢰성, 보안성 등에 대한 시험을 통과해야 얻을 수 있는 인증입니다.<\/p>\n    <\/div>\n    <div class=\"marks rv\">\n      <figure class=\"mark\"><img src=\"assets/mark_gs.png\" alt=\"GS(Good Software) 1등급 인증 마크\" width=\"185\" height=\"101\" loading=\"lazy\"><figcaption>GS 1등급 인증<span>한국정보통신기술협회<\/span><\/figcaption><\/figure>\n      <figure class=\"mark\"><img src=\"assets/mark_kipo.png\" alt=\"특허청\" width=\"185\" height=\"101\" loading=\"lazy\"><figcaption>특허 등록<span>제10-1744956<\/span><\/figcaption><\/figure>\n      <div class=\"crit\">\n        <p>이런 항목을 시험해 통과했습니다<\/p>\n        <ul><li>기능적합성<\/li><li>성능효율성<\/li><li>사용성<\/li><li>신뢰성<\/li><li>보안성<\/li><\/ul>\n      <\/div>\n    <\/div>\n  <\/div>\n<\/section>\n\n<section class=\"closing\" id=\"contact\" aria-labelledby=\"cl-title\">\n  <div class=\"wrap\">\n    <img class=\"sym\" src=\"assets/smarttopo_logo_white.svg\" alt=\"SmartTopo\" width=\"191\" height=\"34\">\n    <h2 id=\"cl-title\">새로운 SmartTopo, 현장에서 직접 확인하세요<\/h2>\n    <p>더 편리해진 메뉴와 사진 측량, 기준점 측량 보고서까지.<br>측량 현장의 단계를 줄인 새 버전을 만나보세요.<\/p>\n    <div class=\"ctas\" style=\"display:flex;gap:12px;flex-wrap:wrap;justify-content:center;margin-top:10px\">\n      <a class=\"btn btn-blue mag\" href=\"#contact\" data-placeholder=\"download\">앱 다운로드<\/a>\n      <a class=\"btn btn-ghost mag\" href=\"https://stopo.co.kr/bbs/?so_table=movie\" target=\"_blank\" rel=\"noopener\" aria-label=\"동영상 매뉴얼 (새 창)\">동영상 매뉴얼<\/a>\n    <\/div>\n  <\/div>\n<\/section>\n\n<\/div>\n<script>\n(()=>{\nconst RM=matchMedia('(prefers-reduced-motion: reduce)').matches;\nconst R=document.getElementById('st26'),$=s=>R.querySelector(s);\n\n/* ---------- device chrome: Android status bar + media area + gesture bar ---------- */\n/* 목업 상태바 시간: 보는 사람의 현재 시각(안드로이드처럼 24시간, 예 9:05·15:30), 10초마다 갱신 */\nconst hm=()=>{const d=new Date();return d.getHours()+':'+String(d.getMinutes()).padStart(2,'0')};\nsetInterval(()=>{const t=hm();R.querySelectorAll('.sbar .tm').forEach(e=>{if(e.textContent!==t)e.textContent=t})},10000);\nconst SB='<div class=\"sbar\" aria-hidden=\"true\"><span class=\"tm\">'+hm()+'<\/span><span class=\"ic\">'+\n '<svg viewBox=\"0 0 18 14\"><path d=\"M9 13.5 0 4.2A13 13 0 0 1 18 4.2z\" opacity=\".95\"/><\/svg>'+\n '<svg viewBox=\"0 0 16 14\"><path d=\"M0 14h3v-3H0zm4.3 0h3V8h-3zm4.4 0h3V4.5h-3zM13 14h3V0h-3z\"/><\/svg>'+\n '<svg viewBox=\"0 0 27 14\"><rect x=\".75\" y=\".75\" width=\"22.5\" height=\"12.5\" rx=\"3.5\" fill=\"none\" stroke=\"#fff\" stroke-width=\"1.5\" opacity=\".6\"/><rect x=\"2.6\" y=\"2.6\" width=\"17.9\" height=\"8.8\" rx=\"2\"/><path d=\"M24.8 4.8h.8a1.2 1.2 0 0 1 1.2 1.2v2a1.2 1.2 0 0 1-1.2 1.2h-.8z\" opacity=\".6\"/><\/svg>'+\n '<span class=\"bt\">94<\/span><\/span><\/div>';\nfunction dev(scr){if(scr.querySelector('.media'))return;const m=document.createElement('div');m.className='media';\n  const ph=scr.parentElement;if(ph&&ph.classList.contains('phone')){const sh=document.createElement('div');sh.className='shell';ph.insertBefore(sh,scr);sh.appendChild(scr);}\n  while(scr.firstChild)m.appendChild(scr.firstChild);scr.insertAdjacentHTML('afterbegin',SB);scr.appendChild(m);\n  scr.insertAdjacentHTML('beforeend','<div class=\"foot\" aria-hidden=\"true\"><\/div>');\n}\nR.querySelectorAll('.phone .screen').forEach(dev);\nR.querySelectorAll('video[autoplay]').forEach(v=>v.play().catch(()=>{}));\n\n/* ---------- data ---------- */\nconst F=[\n {id:'f1',t:'더 편리해진 메뉴 접근성',s:'하단 탭 메뉴로 원하는 기능에 바로',d:'메뉴를 화면 하단 탭으로 바꿔 원하는 기능에 훨씬 빨리 닿습니다. 전체 메뉴 → 서브 메뉴 → 기능으로 들어가던 과정이 하단 탭 → 기능으로 줄어, 메뉴 진입 단계가 최소화되고 작업 속도가 빨라집니다.',v:'f1',im:['s1a','s1b'],alt:['작업 탭 화면','측량 탭 화면']},\n {id:'f2',fc:'#fbfefb',t:'빠른 측설',s:'지도에서 스냅으로 선택하면 바로 측설',d:'지도 위 측설점을 스냅으로 선택하면 곧바로 측설이 시작됩니다. 측설점을 따로 등록하는 과정 없이 지도에서 바로 작업해 측설 속도가 한층 빨라집니다.',v:'f2',im:['s2a','s2b'],alt:['지도에서 측설점 스냅 선택','선택 즉시 측설 시작']},\n {id:'f3',fc:'#fbfefb',t:'측량 단계 간소화',s:'측량 화면에서 설정 후 바로 측량',d:'측량 전 설정 단계를 줄여 지도 화면에서 바로 측량할 수 있습니다. 일반측량 → 측량 준비 화면 → 측량 시작이던 흐름이 일반측량 → 측량 시작으로 바뀌었습니다.',v:'f3',im:['s3a','s3b'],alt:['지도 화면에서 측량','측량 진행 화면']},\n {id:'f4',fc:'#fbfefb',t:'사진 측량',s:'폴대를 세울 수 없는 위치도 사진으로',d:'건물 모서리 등 폴대를 세울 수 없어 측량하기 어려운 위치도 측량할 수 있습니다. 해당 위치를 사진으로 촬영한 뒤, 사진에서 원하는 지점을 선택하면 좌표가 추출됩니다.',v:'f4',im:['s4a','s4b'],alt:['여러 각도에서 자동 촬영','사진에서 지점 선택 후 좌표 추출']},\n {id:'f5',fc:'#fbfefb',t:'사진으로 좌표 입력',s:'포인트점·측설점·도로 IP 좌표를 찍어서 추가',d:'측설점이나 도로 IP점의 좌표를 직접 타이핑하지 않아도 됩니다. 자료를 카메라로 찍거나 앨범에서 불러오면 사진 속 좌표를 자동으로 읽어 바로 추가합니다.',v:'f5',im:['s5a','s5b'],alt:['좌표 영역을 드래그해 인식','인식된 좌표 목록']},\n {id:'f6',fc:'#fbfefb',t:'기준점측량 지원',s:'공공측량 작업규정에 맞춘 측량부터 보고서까지',d:'공공측량 작업규정에 맞춰 설정되어 있어, 기준점측량부터 공공측량 형식의 보고서 출력까지 한 번에 끝낼 수 있습니다.',v:'f6',im:['s6a'],alt:['기준점측량 진행 화면'],report:true}\n];\nconst U=[\n {k:'Snap',t:'스냅 기능 확대',d:'측량 및 측설 화면에서 지도상의 위치를 스냅 기능으로 쉽게 선택하고, 즉시 작업을 수행할 수 있습니다.',im:'u_snap',crop:'full',nofoot:true},\n {k:'Stakeout',t:'측설 추가 간소화',d:'측설 화면에서 측설점을 바로 추가할 수 있습니다.',im:'u_addlist',crop:'full',nofoot:true},\n {k:'Stakeout nav',t:'측설 네비게이션 바',d:'현재 위치에서 측설점까지 가야 할 방향을 화면에 보여줍니다. 측설점에 가까워지면 안내 화면이 눈에 띄게 바뀌어 목표 지점을 쉽게 찾을 수 있습니다.',im:'nav1m',seq:[['nav1m','반경 1m'],['nav30','반경 30cm'],['nav10','반경 10cm']],crop:'full',nofoot:true},\n {k:'VRS',t:'VRS 서버 설정 및 연결 편의성 강화',d:'여러 VRS 서버 정보를 사전에 등록하고 목록으로 관리할 수 있습니다. VRS 연결 시 별도의 정보 입력 없이 등록된 서버를 선택하여 빠르고 간편하게 연결할 수 있어, 현장에서 보다 효율적인 측량 작업이 가능합니다.',im:'u_vrs',crop:'top'},\n {k:'RTK',t:'RTK 설정 불러오기',d:'최근 설정값이 자동으로 저장돼 다시 입력하지 않아도 RTK를 바로 실행합니다. 이전 설정값도 저장되어 필요할 때 골라 바꿀 수 있습니다.',im:'u_rtk',crop:'top'},\n {k:'Drawing',t:'선끼리 병합',d:'도면에서 서로 떨어져 있는 선을 하나로 합칩니다. 두 개로 나뉜 선도 한 번에 이어서 측설할 수 있습니다.',im:'u_merge',crop:'bottom',fc:'#fbfefb'},\n {k:'Import',t:'DXF 포인트 가져오기',d:'포인트 매니저에서 DXF 도면 파일의 포인트를 바로 불러옵니다.',im:'u_dxf',crop:'bottom',fc:'#fbfefb'},\n {k:'Export',t:'CSV 내보내기',d:'포인트 매니저의 포인트 목록을 파일명을 지정해 CSV로 내보냅니다.',im:'u_csv',crop:'bottom',fc:'#fbfefb'},\n {k:'Weather',t:'현장 날씨 안내',d:'현재 위치의 기상청 날씨와 2시간 후 예보를 표시합니다.',im:'u_weather',crop:'zoom',cx:.646,right:.99,fy:.44}\n];\n\n/* ---------- build features ---------- */\nconst list=$('#flist'),rail=$('#rail'),scr=$('#stageScreen .media');\nconst play='<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M8 5v14l11-7z\"/><\/svg>';\nF.forEach((f,i)=>{\n  const a=document.createElement('article');a.className='fitem';a.id=f.id;a.dataset.i=i;\n  a.innerHTML=`<p class=\"no\">${i+1}<\/p><h3>${f.t}<\/h3><p class=\"sum\">${f.s}<\/p><p class=\"desc\">${f.d}<\/p>\n  <div class=\"thumbs\" role=\"group\" aria-label=\"${f.t} 화면\">\n    <button type=\"button\" class=\"thumb vid\" id=\"t${i}v\" data-f=\"${i}\" data-src=\"\" aria-pressed=\"true\">${play}영상<\/button>\n    ${f.im.map((m,j)=>`<button type=\"button\" class=\"thumb\" id=\"t${i}-${j}\" data-f=\"${i}\" data-src=\"assets/${m}.webp\" aria-pressed=\"false\" aria-label=\"${f.alt[j]}\"><img src=\"assets/${m}.webp\" alt=\"\" loading=\"lazy\"><\/button>`).join('')}\n  <\/div>\n  ${f.report?`<figure class=\"report\" style=\"margin:0\"><figcaption>[ 출력 보고서 양식 ]<\/figcaption><img src=\"assets/report.webp\" alt=\"공공측량 형식의 기준점측량 출력 보고서\" loading=\"lazy\"><\/figure>`:''}\n  <div class=\"m-phone\"><div class=\"phone\"${f.fc?` style=\"--foot:${f.fc}\"`:''}><div class=\"screen\"><video data-src=\"assets/${f.v}.mp4\" poster=\"assets/${f.im[0]}.webp\" muted loop playsinline preload=\"none\" aria-label=\"${f.t} 화면 녹화\"><\/video><\/div><\/div><\/div>`;\n  list.appendChild(a);\n  const v=document.createElement('video');Object.assign(v,{muted:true,loop:true,playsInline:true,preload:'none'});\n  v.setAttribute('muted','');v.setAttribute('playsinline','');v.dataset.src=`assets/${f.v}.mp4`;v.poster=`assets/${f.im[0]}.webp`;v.setAttribute('aria-label',f.t+' 화면 녹화');if(f.fc)v.style.setProperty('--foot',f.fc);\n  scr.appendChild(v);\n  const t=document.createElement('i');t.innerHTML=`<span>${f.t}<\/span>`;rail.appendChild(t);\n});\n/* 이미지 레이어 2장을 번갈아 써서 이미지→이미지로 바뀔 때도 전환 효과가 나오게 함 */\nconst stills=[0,1].map(()=>{const m=document.createElement('img');m.alt='';scr.appendChild(m);return m});\nlist.querySelectorAll('.m-phone .screen').forEach(dev);\nconst vids=[...scr.querySelectorAll('video')],ticks=[...rail.children];\nlet cur=-1,layer=null;\nfunction show(el){ if(layer===el) return; if(layer){layer.classList.remove('on');layer.classList.add('was');const old=layer;setTimeout(()=>old.classList.remove('was'),720);scr.classList.remove('swap');void scr.offsetWidth;scr.classList.add('swap')} el.classList.remove('was');el.classList.add('on');layer=el; }\nfunction vidOn(i){const v=vids[i];if(!v.src)v.src=v.dataset.src;vids.forEach((x,j)=>{if(j!==i)x.pause()});if(!RM)v.play().catch(()=>{});show(v)}\nfunction setActive(i){\n  if(i===cur) return; cur=i;\n  ticks.forEach((t,j)=>t.classList.toggle('on',j===i));\n  list.querySelectorAll(`.fitem[data-i=\"${i}\"] .thumb`).forEach(b=>b.setAttribute('aria-pressed',b.classList.contains('vid')));\n  vidOn(i);\n  if(i+1<vids.length&&!vids[i+1].src){vids[i+1].src=vids[i+1].dataset.src;vids[i+1].preload='metadata'}\n}\nlist.addEventListener('click',e=>{\n  const b=e.target.closest('.thumb');if(!b)return;\n  const i=+b.dataset.f;setActive(i);\n  b.parentElement.querySelectorAll('.thumb').forEach(x=>x.setAttribute('aria-pressed',x===b));\n  if(b.classList.contains('vid')){vidOn(i)}else{if(layer&&layer.tagName==='IMG'&&layer.getAttribute('src')===b.dataset.src)return;const still=stills[0]===layer?stills[1]:stills[0];still.src=b.dataset.src;still.alt=b.getAttribute('aria-label');still.style.setProperty('--foot',F[i].fc||'#f0f1f4');vids[i].pause();show(still)}\n});\nconst desk=matchMedia('(min-width: 961px)');\nconst io=new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting&&desk.matches)setActive(+e.target.dataset.i)})},{rootMargin:'-45% 0px -45% 0px'});\nlist.querySelectorAll('.fitem').forEach(a=>io.observe(a));\nif(desk.matches) setActive(0);\n/* 영상 위 터치 효과: 영상별 터치 시점(초)과 위치(영상 가로·세로 %) — f1 하단 탭(측량·측설·도구·설정) 터치를 녹화 영상에서 읽어 맞춤 */\nconst TAPS={hero:[[6.82,84,92],[15.4,42.5,26],[18.48,40,25.8],[19.57,65.7,28],[24.41,38,25.3],[28.98,88.7,24.8],[30.26,67.5,95],[33.37,85,83.4]],   /* 상단 목업: 빠른 측설(0s) → 사진 측량(6.57s) → 측량 단계 간소화(32.4s) 이어 붙인 영상 */\n  f3:[[0.97,85,83.4]],   /* 측량 단계 간소화: 화면을 1초 보여준 뒤 '측량하기' 버튼 */\n  f4:[[0.25,84,92],[8.83,42.5,26],[11.91,40,25.8],[13.0,65.7,28],[17.84,38,25.3],[22.41,88.7,24.8],[23.69,67.5,95]],   /* 사진 측량: 촬영하기 → 사진 썸네일 선택 → 저장 */\n  f5:[[2.93,50,80.3],[4.0,58,89.5],[5.04,60,88],[7.9,72.5,96.3],[11.5,75,95.3],[13.88,13,21.5],[19.7,72.5,17.8],[21.4,80,23.5],[22.85,80,95.8],[27.62,35,95.8]],   /* 사진으로 좌표 입력: 측설목록 → 가져오기 → 사진 → 확인 → 촬영 → 영역 드래그 → 행 선택 → 가져오기 → 취소 */\n  f6:[[1.07,86.5,94.9],[3.49,41,87],[5.53,67.8,96.3]],   /* 기준점측량: 측량하기 → 자동설정 후 측량 → 적용 */\n  f1:[[0.03,10.5,96.6],[1.02,32.3,96.9],[2.49,56.3,96.3],[4.07,71.3,95.8],[5.49,89.8,95.6]]};\nfunction tapAt(v,x,y){const ph=v.closest('.phone');if(!ph)return;const a=v.getBoundingClientRect(),b=ph.getBoundingClientRect(),k=ph.offsetWidth/b.width||1;\n  const d=document.createElement('span');d.className='tapfx';d.style.left=((a.left-b.left)+a.width*x/100)*k+'px';d.style.top=((a.top-b.top)+a.width*766/400*y/100)*k+'px';ph.appendChild(d);setTimeout(()=>d.remove(),800)}\nif(!RM) R.querySelectorAll('video').forEach(v=>{\n  const key=(v.dataset.src||v.getAttribute('src')||'').replace(/^.*\\/|\\.mp4$/g,''),T=TAPS[key];if(!T)return;\n  let last=0,run=false;\n  const tick=()=>{if(v.paused||v.ended){run=false;return}\n    const ct=v.currentTime;if(ct<last)last=-1;                         // 반복 재생으로 처음으로 돌아감\n    T.forEach(([t,x,y])=>{if(t>last&&t<=ct&&ct-t<.4)tapAt(v,x,y)});\n    last=ct;requestAnimationFrame(tick)};\n  v.addEventListener('playing',()=>{last=v.currentTime;if(!run){run=true;requestAnimationFrame(tick)}});\n  if(!v.paused&&!run){last=v.currentTime;run=true;requestAnimationFrame(tick)}   // 상단 목업처럼 이미 재생 중인 영상\n});\n/* mobile inline videos */\nconst mio=new IntersectionObserver(es=>es.forEach(e=>{const v=e.target;if(e.isIntersecting){if(!v.src)v.src=v.dataset.src;if(!RM)v.play().catch(()=>{})}else v.pause()}),{threshold:.35});\nlist.querySelectorAll('.m-phone video').forEach(v=>mio.observe(v));\n\n/* ---------- updates ---------- */\nconst car=$('#ucar');\nU.forEach(u=>{const f=document.createElement('figure');f.className='uitem';\n  const ims=u.seq?u.seq.map(([m,l],j)=>`<img${j?' class=\"off\"':''} src=\"assets/${m}.webp\" alt=\"${u.t}, ${l}\" loading=\"lazy\" width=\"540\" height=\"1033\">`).join('')\n    :`<img src=\"assets/${u.im}.webp\" alt=\"${u.t} 화면\" loading=\"lazy\" width=\"540\" height=\"1033\">`;\n  f.innerHTML=`<div class=\"utile\">${u.seq?`<span class=\"tag\" aria-hidden=\"true\">${u.seq[0][1]}<\/span>`:''}<div class=\"phone${u.nofoot?' nofoot':''}\"${u.fc?` style=\"--foot:${u.fc}\"`:''}><div class=\"screen\">${ims}<\/div><\/div><\/div><figcaption><b>${u.t}.<\/b> ${u.d}<\/figcaption>`;\n  f._u=u;car.appendChild(f)});\ncar.querySelectorAll('.screen').forEach(dev);\n/* phone is centred with roomy side margins; only the top and/or bottom is cropped:\n   bottom = whole lower part shown, top cropped · top = upper part shown · center = feature point in the middle · full = whole phone */\nfunction placeTiles(){car.querySelectorAll('.uitem').forEach(f=>{const u=f._u,t=f.querySelector('.utile'),ph=f.querySelector('.phone');\n  const W=t.clientWidth,H=t.clientHeight,m=Math.round(W*.065);\n  let pw=W*.775;\n  /* zoom: right edge pinned at u.right·W; width chosen so screen point u.cx lands at the card centre */\n  if(u.crop==='zoom')pw=(u.right-.5)*W/(1-10/330-u.cx*(1-20/330));\n  const K=1/330,CH=u.nofoot?58:84,chromeH=p=>p*CH*K,mediaH=p=>p*(1-20*K)*766/400;   /* bezel + status bar scale with the phone */\n  if(u.crop==='full')pw=Math.min(pw,(H-2*m)/((1-20*K)*766/400+CH*K));   /* full: whole phone fits in the tile */\n  const mh=mediaH(pw),phH=mh+chromeH(pw),pad=pw*10*K,head=pw*48*K;\n  let top;\n  if(u.crop==='full') top=(H-phH)/2;\n  else if(u.crop==='bottom') top=H-phH-m*3;\n  else if(u.crop==='top') top=m*3;\n  else top=Math.min(m,Math.max(H-phH-m,H/2-(head+u.fy*mh)));\n  let left=(W-pw)/2;\n  if(u.crop==='zoom'){left=u.right*W-pw;top=H/2-(head+u.fy*mh);}\n  ph.style.width=pw+'px';ph.style.left=left+'px';ph.style.top=top+'px';})}\nnew ResizeObserver(placeTiles).observe(car);placeTiles();\n/* Stakeout nav card: steps through 반경 1m → 30cm → 10cm while it is on screen */\ncar.querySelectorAll('.uitem').forEach(f=>{const u=f._u;if(!u.seq||RM)return;\n  const im=[...f.querySelectorAll('.media>img')],tag=f.querySelector('.tag');let i=0,T;\n  const go=()=>{i=(i+1)%im.length;im.forEach((m,j)=>m.classList.toggle('off',j!==i));tag.textContent=u.seq[i][1]};\n  new IntersectionObserver(es=>{clearInterval(T);if(es[0].isIntersecting)T=setInterval(go,2200)},{threshold:.5}).observe(f);});\nconst ucPrev=$('#ucPrev'),ucNext=$('#ucNext');\nfunction stepW(){const it=car.querySelector('.uitem');return it.getBoundingClientRect().width+22}\nfunction ucState(){ucPrev.disabled=car.scrollLeft<4;ucNext.disabled=car.scrollLeft+car.clientWidth>=car.scrollWidth-4}\nucPrev.addEventListener('click',()=>car.scrollBy({left:-stepW(),behavior:RM?'auto':'smooth'}));\nucNext.addEventListener('click',()=>car.scrollBy({left:stepW(),behavior:RM?'auto':'smooth'}));\ncar.addEventListener('scroll',ucState,{passive:true});addEventListener('resize',ucState);ucState();\n\n/* ---------- live readout ---------- */\nconst base={cx:549278.428,cy:194656.079,cz:27.063};\nif(!RM) setInterval(()=>{\n  for(const k in base){const d=(Math.random()-.5)*.012;$('#'+k).textContent=(base[k]+d).toFixed(3)}\n  $('#ph').textContent=(0.012+Math.random()*.008).toFixed(3);$('#pv').textContent=(0.024+Math.random()*.01).toFixed(3);\n  $('#gn').textContent=15+Math.round(Math.random()*3);\n},900);\n\n/* ---------- hero parallax + reticle ---------- */\nconst hero=$('.hero'),ret=$('.reticle'),tag=ret.querySelector('.tag'),rh=ret.querySelector('.h'),rv=ret.querySelector('.v');\nconst outs=[...R.querySelectorAll('.readout')];\nhero.addEventListener('pointermove',e=>{\n  const r=hero.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;\n  rh.style.top=y+'px';rv.style.left=x+'px';tag.style.left=x+'px';tag.style.top=y+'px';\n  tag.textContent=`X ${(549300-y*.05).toFixed(3)}  Y ${(194600+x*.05).toFixed(3)}`;\n  if(RM)return;const nx=x/r.width-.5,ny=y/r.height-.5;\n  outs.forEach(o=>{const d=+o.dataset.depth;o.style.transform=`translate(${nx*d}px,${ny*d}px)`});\n});\n/* magnetic buttons */\nif(!RM&&matchMedia('(hover:hover)').matches) R.querySelectorAll('.mag').forEach(b=>{\n  b.addEventListener('pointermove',e=>{const r=b.getBoundingClientRect();b.style.transform=`translate(${(e.clientX-r.left-r.width/2)*.18}px,${(e.clientY-r.top-r.height/2)*.28}px)`});\n  b.addEventListener('pointerleave',()=>b.style.transform='');\n});\n\n/* ---------- survey-map background (지도 느낌): 좌표 격자 · 지적 필지 · 도로 + 천천히 흐르는 지도 · 밝아졌다 사라지는 구역 · 흐르는 도로 중앙선 · 측점 펄스 ---------- */\nconst cv=$('#topo'),cx=cv.getContext('2d'),INK='0,99,163',AMP=1;\nlet W,H,DPR,t=0,vis=true,mapImg,PAD=160,roads=[],marks=[];\nconst C=a=>`rgba(${INK},${Math.min(1,a*AMP).toFixed(3)})`;\nfunction rnd(s){return()=>(s=(s*16807)%2147483647)/2147483647}\nfunction build(){\n  const r=rnd(20261),BW=W+PAD*2,BH=H+PAD*2;\n  mapImg=document.createElement('canvas');mapImg.width=BW*DPR;mapImg.height=BH*DPR;\n  const g=mapImg.getContext('2d');g.setTransform(DPR,0,0,DPR,0,0);g.lineCap='round';g.lineJoin='round';\n  /* coordinate grid + crosses */\n  g.lineWidth=1;g.strokeStyle=C(.045);g.beginPath();\n  for(let x=0;x<BW;x+=120){g.moveTo(x+.5,0);g.lineTo(x+.5,BH)}for(let y=0;y<BH;y+=120){g.moveTo(0,y+.5);g.lineTo(BW,y+.5)}g.stroke();\n  g.strokeStyle=C(.16);g.beginPath();\n  for(let x=0;x<BW;x+=120)for(let y=0;y<BH;y+=120){g.moveTo(x-5,y+.5);g.lineTo(x+5,y+.5);g.moveTo(x+.5,y-5);g.lineTo(x+.5,y+5)}g.stroke();\n  /* cadastral parcels: rows of lots in a slightly rotated frame, a few lots shaded like buildings */\n  g.save();g.translate(BW/2,BH/2);g.rotate(-.3);const RR=Math.hypot(BW,BH)/2+80,lots=[];\n  g.beginPath();\n  for(let y=-RR;y<RR;){const h=46+r()*42;g.moveTo(-RR,y);g.lineTo(RR,y);\n    for(let x=-RR+r()*50;x<RR;){const w=26+r()*64,k=(r()-.5)*12;g.moveTo(x,y);g.lineTo(x+k,y+h);if(r()<.13)lots.push([x+4,y+4,w-8,h-8]);x+=w}\n    y+=h}\n  g.lineWidth=.8;g.strokeStyle=C(.11);g.stroke();\n  g.fillStyle=C(.05);lots.forEach(l=>g.fillRect(...l));\n  g.restore();\n  /* roads: cut the lots, then draw kerb lines and a dashed centre line */\n  roads=[[-20,BH*.66, BW*.3,BH*.5, BW*.62,BH*.62, BW+20,BH*.3],\n         [BW*.58,-20, BW*.66,BH*.35, BW*.56,BH*.7, BW*.74,BH+20],\n         [BW*.05,-20, BW*.2,BH*.3, BW*.08,BH*.6, BW*.3,BH+20]];\n  const path=r=>{g.beginPath();g.moveTo(r[0],r[1]);g.bezierCurveTo(r[2],r[3],r[4],r[5],r[6],r[7])};\n  roads.forEach((rd,i)=>{const w=i===0?20:14;\n    const cut=lw=>{g.globalCompositeOperation='destination-out';g.strokeStyle='#000';path(rd);g.lineWidth=lw;g.stroke();g.globalCompositeOperation='source-over'};\n    cut(w+2);path(rd);g.lineWidth=w+2;g.strokeStyle=C(.2);g.stroke();     /* kerb lines */\n    cut(w);path(rd);g.lineWidth=w;g.strokeStyle=C(.07);g.stroke();});      /* road surface (centre line is drawn live) */\n  /* survey control points (pulsing) */\n  marks=[];for(let i=0;i<16;i++)marks.push([PAD*.5+r()*(BW-PAD),PAD*.5+r()*(BH-PAD),r()*6.28]);\n}\nconst mkc=document.createElement('canvas'),mk=mkc.getContext('2d');\nfunction size(){DPR=Math.min(2,devicePixelRatio||1);W=cv.clientWidth;H=cv.clientHeight;cv.width=W*DPR;cv.height=H*DPR;cx.setTransform(DPR,0,0,DPR,0,0);mkc.width=W;mkc.height=H;build()}\nfunction draw(){\n  cx.clearRect(0,0,W,H);\n  /* the map pans and zooms in and out, so its lines keep sliding and growing across the background */\n  const ox=-PAD+Math.sin(t*.23)*PAD*.85,oy=-PAD+Math.cos(t*.17)*PAD*.7,sc=1.14+.16*Math.sin(t*.15);\n  const fx=W*.62,fy=H*.5;\n  cx.save();cx.translate(fx,fy);cx.scale(sc,sc);cx.translate(-fx+ox,-fy+oy);\n  cx.drawImage(mapImg,0,0,mapImg.width/DPR,mapImg.height/DPR);\n  cx.lineWidth=1;cx.setLineDash([7,9]);cx.lineDashOffset=-t*60;cx.strokeStyle=C(.2);\n  roads.forEach(r=>{cx.beginPath();cx.moveTo(r[0],r[1]);cx.bezierCurveTo(r[2],r[3],r[4],r[5],r[6],r[7]);cx.stroke()});\n  cx.setLineDash([]);\n  marks.forEach(([x,y,p])=>{\n    cx.strokeStyle=C(.3);cx.lineWidth=1.2;cx.beginPath();cx.moveTo(x,y-5);cx.lineTo(x+4.5,y+3);cx.lineTo(x-4.5,y+3);cx.closePath();cx.stroke();\n    const k=((t*.35+p)%6.28)/6.28;if(k<.35){const q=k/.35;cx.strokeStyle=C(.28*(1-q));cx.beginPath();cx.arc(x,y,6+q*26,0,6.28);cx.stroke()}});\n  cx.restore();\n  /* drifting light patches: parts of the map brighten and fade as they pass */\n  mk.clearRect(0,0,W,H);mk.globalCompositeOperation='source-over';mk.fillStyle='rgba(0,0,0,.3)';mk.fillRect(0,0,W,H);mk.globalCompositeOperation='lighter';\n  for(let i=0;i<4;i++){const x=W*(.5+.42*Math.sin(t*(.21+i*.07)+i*1.9)),y=H*(.5+.4*Math.cos(t*(.17+i*.05)+i*2.7)),rr=Math.max(W,H)*(.26+.06*i);\n    const gr=mk.createRadialGradient(x,y,0,x,y,rr);gr.addColorStop(0,'rgba(0,0,0,.7)');gr.addColorStop(1,'rgba(0,0,0,0)');mk.fillStyle=gr;mk.fillRect(0,0,W,H)}\n  cx.globalCompositeOperation='destination-in';cx.drawImage(mkc,0,0,W,H);cx.globalCompositeOperation='source-over';\n  /* fade everything out behind the text column */\n  const m=cx.createLinearGradient(0,0,W,0);m.addColorStop(0,'rgba(0,0,0,.25)');m.addColorStop(.45,'rgba(0,0,0,.6)');m.addColorStop(1,'rgba(0,0,0,1)');\n  cx.globalCompositeOperation='destination-in';cx.fillStyle=m;cx.fillRect(0,0,W,H);cx.globalCompositeOperation='source-over';\n}\nfunction loop(){if(vis){t+=.006;draw()}requestAnimationFrame(loop)}\nsize();draw();addEventListener('resize',()=>{size();draw()});\nnew IntersectionObserver(es=>vis=es[0].isIntersecting).observe(hero);\nif(!RM) requestAnimationFrame(loop);\n\n/* ---------- in-page links: smooth eased scroll instead of a jump ---------- */\nfunction headerOffset(){            // site header fixed/sticky at the top, if any\n  for(const el of document.elementsFromPoint(innerWidth/2,2)){\n    if(R.contains(el)) continue;\n    for(let n=el;n&&n!==document.body;n=n.parentElement){\n      const p=getComputedStyle(n).position;\n      if(p==='fixed'||p==='sticky') return Math.max(0,n.getBoundingClientRect().bottom);\n    }\n  }\n  return 0;\n}\nconst jump=y=>scrollTo({top:y,behavior:'instant'});   // bypass any site-wide scroll-behavior\nconst ease=x=>x<.5?4*x*x*x:1-Math.pow(-2*x+2,3)/2;\nlet anim=0;\nR.querySelectorAll('a[href^=\"#\"]').forEach(a=>a.addEventListener('click',e=>{\n  const id=a.getAttribute('href').slice(1), target=id&&R.querySelector('#'+CSS.escape(id));\n  if(!target) return;\n  e.preventDefault();\n  const y0=scrollY, y1=Math.max(0,target.getBoundingClientRect().top+scrollY-headerOffset());\n  if(RM){jump(y1);return}\n  const d=y1-y0, dur=Math.min(1400,Math.max(600,Math.abs(d)*.45)), t0=performance.now(), my=++anim;\n  const stop=()=>{anim++;removeEventListener('wheel',stop);removeEventListener('touchstart',stop)};\n  addEventListener('wheel',stop,{passive:true});addEventListener('touchstart',stop,{passive:true});\n  (function step(now){\n    if(my!==anim) return;\n    const k=Math.min(1,(now-t0)/dur);\n    jump(y0+d*ease(k));\n    if(k<1) requestAnimationFrame(step); else stop();\n  })(t0);\n}));\n})();\n<\/script>\n<\/div>\n<!-- ===== SmartTopo 2026 소개 페이지 끝 ===== -->\n\n<\/body>\n<\/html>\n"};
